static decimal ApplyDiscount(decimal price, decimal percent = 0)
{
    if (price < 0) throw new ArgumentOutOfRangeException(nameof(price));
    if (percent is < 0 or > 100) throw new ArgumentOutOfRangeException(nameof(percent));
    return price - (price * percent / 100m);
}

var finalPrice = ApplyDiscount(1_000_000m, 15);
Console.WriteLine(finalPrice);

static int Sum(params int[] values) => values.Sum();

static bool TryParseAge(string text, out int age)
{
    return int.TryParse(text, out age) && age >= 0;
}

static void Increase(ref int value) => value++;
